const raw = $json;
const isWebhook = raw.body !== undefined || raw.headers !== undefined;

let normalized;
if (isWebhook) {
  const body = raw.body || raw;
  normalized = {
    source_type: body.source_type || 'social_media',
    competitor_name: body.competitor_name || 'Unknown Competitor',
    title: body.title || 'Untitled Update',
    link: body.link || body.url || '',
    content_snippet: body.content || body.text || '',
    published_date: body.published_date || new Date().toISOString()
  };
} else {
  let competitorName = 'Unknown Competitor';
  try {
    competitorName = new URL(raw.link).hostname.replace('www.', '');
  } catch (e) {
    competitorName = raw.creator || 'Unknown Competitor';
  }
  normalized = {
    source_type: 'rss',
    competitor_name: competitorName,
    title: raw.title || '',
    link: raw.link || '',
    content_snippet: raw.contentSnippet || raw.content || raw.summary || '',
    published_date: raw.isoDate || raw.pubDate || new Date().toISOString()
  };
}

normalized.retryCount = 0;
normalized.retryCountAi = 0;

console.log(`[LOG] Ingestion received | Source: ${normalized.source_type} | Competitor: ${normalized.competitor_name} | Title: ${normalized.title} | Timestamp: ${new Date().toISOString()}`);

return { json: normalized };

let priorCount = 0;
try {
  priorCount = $('Increment Retry Count - Scrape').item.json.retryCount || 0;
} catch (e) {
  priorCount = 0;
}
const retryCount = priorCount + 1;
const original = $('Validate Update Data').item.json;
console.log(`[LOG] Retry attempt ${retryCount} of 3 for scraping | URL: ${original.link}`);
return { json: { ...original, retryCount } };

console.log(`[LOG] Retry exhausted for scraping after 3 attempts | URL: ${$json.link} | Falling back to RSS/webhook snippet content`);
return {
  json: {
    ...$json,
    content: $json.content_snippet,
    scrape_status: 'fallback_snippet'
  }
};

console.log(`[LOG] Scrape successful | URL: ${$json.link}`);

const raw = $json.data || $json.content_snippet || '';
const cleanText = raw
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 6000);

return {
  json: {
    ...$json,
    content: cleanText,
    scrape_status: 'success'
  }
};

const reason = $json.scrape_status
  ? 'Insufficient content after scrape and fallback'
  : 'Missing or invalid required fields (link/title) before scraping';
console.log(`[LOG] Final status: SKIPPED | Reason: ${reason} | Competitor: ${$json.competitor_name} | Link: ${$json.link}`);
return $input.all();

const original = $('Check Content Sufficiency').item.json;
let embeddingVector = null;

try {
  const embedItem = $('Generate Embedding - OpenRouter (bge-m3)').item.json;

  if (embedItem?.data?.[0]?.embedding) {
    embeddingVector = embedItem.data[0].embedding;
  } else if (embedItem?.embedding) {
    embeddingVector = embedItem.embedding;
  } else if (Array.isArray(embedItem?.data) && embedItem.data.length > 0) {
    embeddingVector = embedItem.data[0].embedding || embedItem.data[0] || null;
  }

  if (!Array.isArray(embeddingVector) || embeddingVector.length === 0) {
    embeddingVector = null;
  }

} catch (e) {
  console.error(`[LOG] Embedding extraction error: ${e.message}`);
  embeddingVector = null;
}

if (!embeddingVector) {
  console.log(`[LOG] Embedding generation failed | Competitor: ${original.competitor_name} | Skipping vector storage`);
}

let historicalContext = 'No historical context available for this competitor yet.';
const queryResult = $json;
if (queryResult && Array.isArray(queryResult.matches) && queryResult.matches.length > 0) {
  const lines = queryResult.matches.map(m => {
    const meta = m.metadata || {};
    return `- [${meta.impact_level || 'Unknown'} impact | ${meta.category || 'Unknown'}] ${meta.published_date || 'n/a'}: ${(meta.summary || '').slice(0, 200)}`;
  });
  historicalContext = `Related past updates from this competitor:\n${lines.join('\n')}`;
}

return {
  json: {
    ...original,
    embedding_vector: embeddingVector,
    historical_context: historicalContext
  }
};

