let priorCount = 0;
try {
  priorCount = $('Increment Retry Count - AI Analysis').item.json.retryCountAi || 0;
} catch (e) {
  priorCount = 0;
}
const retryCountAi = priorCount + 1;
const original = $('Format Historical Context').item.json;
console.log(`[LOG] Retry attempt ${retryCountAi} of 3 for AI analysis | Competitor: ${original.competitor_name}`);
return { json: { ...original, retryCountAi } };

console.log(`[LOG] Fallback triggered | Reason: AI analysis unavailable after 3 retries | Competitor: ${$json.competitor_name}`);
return {
  json: {
    ...$json,
    summary: `AI analysis unavailable. Manual review required for this update from ${$json.competitor_name}: ${$json.title}`,
    impact_level: 'Medium',
    category: 'Other',
    strategic_recommendation: 'Manual review recommended - monitor for potential market shift',
    analysis_status: 'fallback'
  }
};

const raw = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '{}';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    summary: 'Unable to parse AI response.',
    impact_level: 'Medium',
    category: 'Other',
    strategic_recommendation: 'Manual review recommended - monitor for potential market shift'
  };
}

const original = $('Format Historical Context').item.json;

const competitorName = original.competitor_name ||
  $('Normalize Update Data').item.json.competitor_name ||
  'Unknown Competitor';

const result = {
  ...original,
  competitor_name: competitorName,
  summary: parsed.summary,
  impact_level: parsed.impact_level,
  category: parsed.category,
  strategic_recommendation: parsed.strategic_recommendation,
  analysis_status: 'success',
  link: original.link || $('Normalize Update Data').item.json.link || '',
  published_date: original.published_date || $('Normalize Update Data').item.json.published_date || new Date().toISOString()
};

console.log(`[LOG] Draft generated | Competitor: ${result.competitor_name} | Category: ${result.category} | Impact: ${result.impact_level}`);
console.log(`[LOG] Analysis complete | Competitor: ${result.competitor_name} | Summary: ${result.summary}`);

return { json: result };

const item = $json;
const safeId = (item.competitor_name || 'unknown-competitor').toLowerCase().replace(/[^a-z0-9]+/g, '-');
const vectorId = `${safeId}-${Date.now()}`;

return {
  json: {
    ...item,
    pinecone_vector_id: vectorId,
    retryCountStore: 0,
    pinecone_metadata: {
      competitor_name: item.competitor_name || '',
      category: item.category || '',
      impact_level: item.impact_level || '',
      source_link: item.link || '',
      published_date: item.published_date || '',
      analysis_status: item.analysis_status || '',
      summary: (item.summary || '').slice(0, 500)
    }
  }
};

let priorCount = 0;
try {
  priorCount = $('Increment Retry Count - Pinecone Store').item.json.retryCountStore || 0;
} catch (e) {
  priorCount = 0;
}
const retryCountStore = priorCount + 1;
const original = $('Prepare Document & Metadata for Vector Store').item.json;
console.log(`[LOG] Retry attempt ${retryCountStore} of 3 for Pinecone storage | Competitor: ${original.competitor_name}`);
return { json: { ...original, retryCountStore } };

const original = $('Prepare Document & Metadata for Vector Store').item.json;

if ($json.error) {
  console.log(`[LOG] Retry exhausted for Pinecone storage after 3 attempts | Competitor: ${original.competitor_name}`);
  console.log(`[LOG] Vector storage failed | Competitor: ${original.competitor_name} | Continuing workflow - insight will not be retrievable via vector search`);
} else {
  console.log(`[LOG] Vector storage complete | Competitor: ${original.competitor_name} | Index: competitor-insights-index`);
}

return { json: original };

const channelMap = {
  'Product Launch': 'product-competitor-alerts',
  'Pricing Change': 'pricing-competitor-alerts',
  'Executive Hire': 'talent-intel-alerts'
};

const slackChannel = channelMap[$json.category] || 'general-competitor-alerts';
const impactEmoji = { High: '🔴', Medium: '🟡', Low: '🟢' }[$json.impact_level] || '⚪';

const message = [
  `${impactEmoji} *Competitor Update Detected* — ${$json.competitor_name}`,
  '',
  `*Title:* ${$json.title}`,
  `*Category:* ${$json.category}`,
  `*Impact Level:* ${$json.impact_level}`,
  '',
  `*Summary:*`,
  $json.summary,
  '',
  `*Strategic Recommendation:*`,
  $json.strategic_recommendation,
  '',
  `*Source:* ${$json.link}`
].join('\n');

return {
  json: {
    ...$json,
    slack_channel: slackChannel,
    slack_message: message,
    retrySlackCount: 0
  }
};

let priorCount = 0;
try {
  priorCount = $('Increment Retry Count - Category Slack').item.json.retrySlackCount || 0;
} catch (e) {
  priorCount = 0;
}
const retrySlackCount = priorCount + 1;
const original = $('Assign Channel & Build Slack Message').item.json;
console.log(`[LOG] Retry attempt ${retrySlackCount} of 3 for Slack delivery | Channel: ${original.slack_channel} | Competitor: ${original.competitor_name}`);
return { json: { ...original, retrySlackCount } };

const original = $('Assign Channel & Build Slack Message').item.json;

if ($json.error) {
  console.log(`[LOG] Final status: FAILURE | Slack delivery failed for category channel after 3 retries | Channel: ${original.slack_channel} | Competitor: ${original.competitor_name}`);
} else {
  console.log(`[LOG] Category channel notification sent | Competitor: ${original.competitor_name} | Channel: ${original.slack_channel}`);
}

return { json: { ...original, retryEscalationCount: 0 } };

let priorCount = 0;
try {
  priorCount = $('Increment Retry Count - Escalation Slack').item.json.retryEscalationCount || 0;
} catch (e) {
  priorCount = 0;
}
const retryEscalationCount = priorCount + 1;
const original = $('Log Category Slack Outcome').item.json;
console.log(`[LOG] Retry attempt ${retryEscalationCount} of 3 for executive escalation Slack delivery | Competitor: ${original.competitor_name}`);
return { json: { ...original, retryEscalationCount } };

const original = $('Log Category Slack Outcome').item.json;
const competitor = original.competitor_name;
const category = original.category;
const impact = original.impact_level;

if ($json.error) {
  console.log(`[LOG] Final status: FAILURE | Executive escalation Slack delivery failed after 3 retries | Competitor: ${competitor}`);
} else {
  console.log(`[LOG] Final status: SUCCESS | Workflow complete | Competitor: ${competitor} | Category: ${category} | Impact: ${impact}`);
}

return { json: original };
